// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, address actor) public {
        amount = bound(amount, 1, 1e30);
        vm.assume(actor != address(c) && actor != address(0));

        // adversarial counterparty: a receiver that rejects incoming funds
        Reverter r = new Reverter();

        vm.deal(address(c), amount);
        uint256 before = address(c).balance;

        // the test contract is the deployer, hence c.owner, so it may call sendTo
        bool ok;
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful sendTo must move exactly `amount` out of c.
        // Reference: transfer reverting makes sendTo revert, so success implies balance dropped by amount.
        // Mutant: failed low-level call is swallowed, sendTo succeeds yet balance is unchanged.
        assertTrue(!ok || address(c).balance == before - amount);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
